if#yT<=3900 then
return yT
end
for zT,AT in ipairs({200,100})do
for BT,CT in ipairs(xT.unit.passives or{})do
CT.text=tostring(CT.text):sub(1,AT)
end
yT=U.json(xT)
if#yT<=3900 then
return yT
end
end
for ET,FT in ipairs(xT.learned or{})do
FT.y=nil
end
xT.unexplained=nil
yT=U.json(xT)
if#yT<=3900 then
return yT
end
for GT,HT in ipairs(xT.unit.attacks or{})do
HT.does=nil
end
if xT.unit.ability then
xT.unit.ability.text=xT.unit.ability.text and xT.unit.ability.text:sub(1,120)
end
xT.run.mates=nil
yT=U.json(xT)
if#yT<=3900 then
return yT
end
xT.unit.attacks=nil
return U.json(xT):sub(1,3900)
end
function db.sendStudy(IT)
