return
end
for JT=1,math.max(1,tonumber(IT)or 1)do
if#P.studyQ==0 then
return
end
local KT=U.now()
while db.sending and U.now()-KT<8 do
task.wait(0.25)
end
if db.sending then
return
end
db.sending=true
local LT,NT=pcall(db.postEmbed,string.format(vee[2799],tostring(P.anonId),j),vee[2800]..P.studyQ[1]..vee[2801])
db.sending=nil
if not(LT and NT)then
return
end
table.remove(P.studyQ,1)
P.studySent=(tonumber(P.studySent)or 0)+1
pcall(F.saveNow)
if#P.studyQ>0 then
task.wait(1.5)
end
end
