for zX,AX in pairs(wX.evolve and wX.evolve.normal and wX.evolve.normal.item_requirement or{})do
local BX=N.SaleEvent[AX.item_id]
if BX and type(BX.resource_cost)==vee[1967]and BX.resource_cost.id==vee[2856]then
