elseif not CX then
yX.step,yX.needCoins=vee[2858],1
elseif yX.item and not yX.haveItem then
yX.step,yX.needCoins=vee[2829],math.max(0,yX.itemCost-yX.coins)
else
yX.step=vee[2063]
end
return yX
end
