function ib.bestInfinite()
local leb,meb
for neb,oeb in ipairs(W.lastScored or{})do
if oeb.kind==vee[1986]and ib.eligible(oeb)then
local peb,qeb=P.train.real[oeb.key],oeb.rec or W.rec(oeb.key)
local reb=(tonumber(qeb.timed)or 0)>0 and qeb.sec/qeb.timed/60 or 0
local seb=(peb and peb.n>0 and reb>0)and(peb.sum/peb.n)/reb or 0
if seb<=0 then
seb=db.hiveTrainRate(oeb.key)or 0
end
if seb>(meb or 0)then
leb,meb=oeb,seb
