end
function ib.perRun(ueb,veb)
local web=P.train.real[ueb]
if web and web.n>0 then
return web.sum/web.n,true
end
local xeb=db.hiveTrain(ueb,veb)
if xeb then
return xeb,true
end
local yeb,zeb=0,0
local Aeb=W.isInf(ueb)
for Beb,Ceb in pairs(P.train.real)do
if W.isInf(Beb)==Aeb then
yeb,zeb=yeb+Ceb.sum,zeb+Ceb.n
end
end
if zeb>0 then
return yeb/zeb,true
end
local Deb=P.trainSim[ueb]
return Deb and Deb.tk and Deb.tk*ib.ratio()or nil,false
end
