function ib.plan(Heb,Ieb,Jeb)
local Keb=N.session()
local Leb=table.clone(Jeb)
table.sort(Leb)
local Meb=table.concat(Leb,vee[2816])
local Neb=(tonumber((P.simCal[Heb.key]or{}).n)or 0)>0
local Oeb=Neb and 1.3 or 2
local Peb=Meb..vee[2281]..Ieb.uuid..(Neb and vee[3131]or vee[3132])..vee[3133]
local Qeb=P.trainSim[Heb.key]
if Qeb and Qeb.sig==Peb and not Qeb.pending and os.time()-(Qeb.at or 0)<6*3600 then
return Qeb
end
local Reb={sig=Peb,base=Meb,uuid=Ieb.uuid,at=os.time(),ok=false,margin=Oeb,pending=true}
P.trainSim[Heb.key]=Reb
local Seb,Teb=gb.levelFor(Heb)
if Heb.ldOverride then
Seb=Heb.ldOverride
end
if not Seb then
Reb.why,Reb.pending=vee[3134],nil
return Reb
end
local Ueb=gb.info(Seb,Heb.key,Teb,Heb.mod)
local Veb={}
for Web,Xeb in ipairs(Jeb)do
local Yeb=Keb.collection:get_unit_by_uuid(Xeb)
if Yeb then
table.insert(Veb,Yeb)
end
end
local Zeb=Keb.collection:get_unit_by_uuid(Ieb.uuid)
if not Zeb or#Veb==0 then
Reb.why,Reb.pending=vee[3135],nil
return Reb
end
local _eb=gb.run(Ueb,gb.teamFrom(Veb,Ueb.map),{hpMul=1})
local afb=Ueb.infinite and gb.unbound(Seb)
local bfb=afb and W.infTier(gb.run(Ueb,gb.teamFrom(Veb,Ueb.map),{hpMul=Oeb}).wave)or nil
local cfb={}
for dfb,efb in ipairs(Veb)do
if not V.isFarm(efb.unit_id)then
local ffb,gfb=pcall(V.score,efb,Heb.mod)
table.insert(cfb,{i=dfb,sc=ffb and gfb or 0})
end
end
table.sort(cfb,function(hfb,ifb)
return hfb.sc<ifb.sc
end)
local jfb
for kfb=1,math.min(3,#cfb)do
local lfb=table.clone(Veb)
lfb[cfb[kfb].i]=Zeb
local mfb=gb.teamFrom(lfb,Ueb.map)
local nfb=gb.run(Ueb,mfb,{hpMul=Oeb,train=Ieb.uuid})
if(afb and W.infTier(nfb.wave)>=bfb)or(not afb and nfb.won)then
local ofb=gb.run(Ueb,mfb,{hpMul=1,train=Ieb.uuid})
local pfb=(ofb.tk or 0)/math.max(0.5,ofb.t/60)
if(ofb.won or afb)and(not jfb or pfb>math.max(jfb.rate*1.5,jfb.rate+1))then
jfb={out=Veb[cfb[kfb].i].unit_id,r=ofb,rate=pfb,trial=lfb}
end
end
end
Reb.ownMin=_eb.t/60
if not jfb then
Reb.why=afb and string.format(vee[3136],bfb,Neb and vee[3137]or vee[3138])or Neb and vee[3139]or vee[3140]
else
Reb.out,Reb.tk,Reb.minutes=jfb.out,jfb.r.tk or 0,jfb.r.t/60
Reb.uuids={}
for qfb,rfb in ipairs(jfb.trial)do
table.insert(Reb.uuids,rfb.uuid)
end
Reb.slow=(_eb.won and not afb)and Reb.minutes/math.max(0.1,Reb.ownMin)or 1
if Reb.tk<=0 and next(P.train.real)==nil then
Reb.why=vee[3141]
elseif Reb.slow>ib.SLOW then
Reb.why=string.format(vee[3142],math.floor((Reb.slow-1)*100+0.5))
else
Reb.ok=true
end
end
Reb.pending=nil
F.log(1,vee[3143],string.format(vee[3144],Heb.label,V.name(Ieb.id),Reb.out and(vee[3145]..V.name(Reb.out))or vee[889],Reb.ok and string.format(vee[3146],math.floor((ib.perRun(Heb.key,Ieb.id)or 0)+0.5),Ieb.what,Reb.minutes,Reb.ownMin)or tostring(Reb.why)))
F.saveSoon()
return Reb
end
