Llb=Llb+1
task.wait(3.5)
continue
end
local Rlb=U.now()
while U.now()-Rlb<4 and Dlb()>=Mlb do
task.wait(0.1)
end
if not Plb or Dlb()>=Mlb then
local Slb=F.gameSaid(Nlb)or Qlb
if tostring(Slb):lower():find(vee[3266])and Llb<3 then
Llb=Llb+1
