for hnb,inb in ipairs(U.list(N.WLO.WORLD_ORDER))do
local jnb=N.Worlds[inb]
if jnb and not jnb.legend_stage and not jnb.raid_world then
local knb=U.list(jnb.levels)
local lnb=knb[#knb]
if lnb and not W.done(dnb,lnb.id,vee[2409])then
enb,fnb,gnb=inb,knb[1],lnb
break
end
end
end
if not(enb and cnb[enb]and fnb and gnb)then
return
end
if W.open(gnb.id)or not W.open(fnb.id)then
return
end
P.worldSkip=type(P.worldSkip)==vee[1967]and P.worldSkip or{}
local mnb=P.worldSkip[enb]
if type(mnb)==vee[1967]and(mnb.done or os.time()-(tonumber(mnb.at)or 0)<ab.WORLD_SKIP_RETRY)then
return
end
local nnb=N.Worlds[enb]
local onb=tostring(nnb and nnb.name or enb)
local pnb={key=vee[2647]..gnb.id..vee[2752],kind=vee[2006],first=true,level=gnb.id,diff=vee[2409],label=W.levelName(gnb.id)..vee[2753]}
local qnb,rnb=pcall(gb.plan,pnb,false)
if not(qnb and type(rnb)==vee[1967])then
return
end
if not rnb.won then
if ab.every(vee[3319]..enb,3600)then
F.log(1,vee[2581],string.format(vee[3320],onb,W.levelName(gnb.id),tostring(rnb.margin)))
end
return
end
local snb={}
for tnb,unb in ipairs(U.list(nnb.levels))do
snb[unb.id]=W.done(dnb,unb.id,vee[2409])
end
local vnb=U.now()
F.log(1,vee[2581],string.format(vee[3321],onb,W.levelName(gnb.id),tostring(rnb.margin)))
local wnb,xnb=F.request(vee[3322],vee[3323],enb)
local ynb=false
while U.now()-vnb<8 do
task.wait(1)
if W.open(gnb.id)then
ynb=true
break
end
end
local znb=F.gameSaid(vnb)
P.worldSkip[enb]={at=os.time(),done=ynb or nil,last=gnb.id,said=znb and tostring(znb):sub(1,80)or nil}
F.saveSoon()
if ynb then
local Anb=(N.prof()or{}).level_data or{}
local Bnb={}
for Cnb,Dnb in ipairs(U.list(nnb.levels))do
if Dnb.id~=gnb.id and not snb[Dnb.id]and W.done(Anb,Dnb.id,vee[2409])then
table.insert(Bnb,W.levelName(Dnb.id))
end
end
F.log(1,vee[2581],string.format(vee[3324],onb,#Bnb>0 and(vee[3325]..table.concat(Bnb,vee[2079]))or vee[3326],znb and(vee[3327]..tostring(znb))or vee[889]))
W.lastScored=nil
else
F.log(1,vee[2581],string.format(vee[3328],onb,tostring(znb or(wnb and xnb)or vee[2552])))
end
end
