function eb.upgradeGain(nxb,oxb,pxb,qxb,rxb,sxb)
local txb,uxb=oxb[pxb],oxb[pxb+1]
local vxb=(txb.cd>0 and txb.damage/txb.cd or 0)
local wxb=(uxb.cd>0 and uxb.damage/uxb.cd or 0)*V.aoe(uxb.atk,uxb.range)/math.max(0.3,V.aoe(txb.atk,txb.range))
local xxb=vxb>0 and nxb*(wxb/vxb-1)or(sxb or 0)
local yxb=oxb[pxb+2]
if yxb and pxb+1<oxb.max and yxb.cd>0 and uxb.cd>0 and vxb>0 then
local zxb=nxb*((yxb.damage/yxb.cd)/vxb-1)
local Axb=qxb+yxb.cost*rxb
if zxb/Axb>xxb/qxb then
xxb=xxb+(zxb/Axb*qxb-xxb)*0.5
end
end
local Bxb=(uxb.range or 0)>(txb.range or 0)and(1+((uxb.range-txb.range)/math.max(1,txb.range)))or 1
return math.max(0,xxb)*Bxb
end
function eb.dpsFor(Cxb,Dxb)
if Dxb<=0 then
return 0
end
local Exb={}
for Fxb,Gxb in ipairs(Cxb)do
if not Gxb.farm and Gxb.gain>0 then
table.insert(Exb,Gxb)
end
end
table.sort(Exb,function(Hxb,Ixb)
return Hxb.gain/Hxb.cost>Ixb.gain/Ixb.cost
end)
local Jxb,Kxb=0,0
for Lxb,Mxb in ipairs(Exb)do
if Dxb<=0 then
break
end
Kxb=Mxb.gain/Mxb.cost
local Nxb=math.min(1,Dxb/Mxb.cost)
Jxb=Jxb+Mxb.gain*Nxb
Dxb=Dxb-Mxb.cost*Nxb
end
return Jxb+math.max(0,Dxb)*Kxb*0.7
end
function eb.shieldDps(Oxb,Pxb,Qxb,Rxb,Sxb,Txb,Uxb)
if(Rxb or 0)<=0 or(Oxb or 0)<=0 or(Sxb or 0)<=0 then
return Oxb or 0
end
Pxb,Qxb,Txb=math.max(0.3,Pxb or 2),math.max(1,Qxb or 1),Txb or 1
local Vxb=Oxb*Txb*Pxb/Qxb
return Sxb*Qxb/((Rxb/math.max(1,Uxb or 1)+math.max(1,Sxb/Vxb))*Pxb)/Txb
end
function eb.shieldGain(Wxb,Xxb,Yxb,Zxb,_xb,ayb,byb,cyb)
local dyb,eyb=V.attackInfo(Xxb.atk,Xxb.range),V.attackInfo(Zxb.atk,Zxb.range)
