local gyb=eb.shieldDps(Yxb,(tonumber(Zxb.cd)or 2)*(byb or 1),eyb.n,_xb,ayb,cyb,eyb.hits)
local hyb=math.max(0,((tonumber(Zxb.range)or 0)-(tonumber(Xxb.range)or 0))/math.max(1,tonumber(Xxb.range)or 1))
