end
agc=ogc
end
end
jb.note(string.format(vee[3893],Xfc,Yfc,Rfc and vee[3894]or(Vfc<=1 and vee[3895]or vee[3896]),jb.luck(Qfc),(tonumber(N.cur(vee[2031]))or 0)-_fc))
local tgc,ugc,vgc=jb.res(jb.data())
