function bb.buildPath()
bb.samples={}
local ykc=N.PATH and N.PATH.PATH_CACHE and N.PATH.PATH_CACHE[workspace._BASES.pve]
if not ykc then
return
end
for zkc,Akc in pairs(ykc)do
if not(N.PATH.HIDDEN_MOCK_LANES and N.PATH.HIDDEN_MOCK_LANES[zkc.Name])then
local Bkc={}
for Ckc,Dkc in ipairs(Akc.points or{})do
table.insert(Bkc,Dkc.part.Position)
end
local Ekc=0
for Fkc=2,#Bkc do
Ekc=Ekc+(Bkc[Fkc]-Bkc[Fkc-1]).Magnitude
end
local Gkc=0
for Hkc=2,#Bkc do
local Ikc,Jkc=Bkc[Hkc-1],Bkc[Hkc]
local Kkc=(Jkc-Ikc).Magnitude
local Lkc=math.max(1,math.floor(Kkc/2))
for Mkc=0,Lkc-1 do
local Nkc=Ikc:Lerp(Jkc,Mkc/Lkc)
table.insert(bb.samples,{pos=Nkc,prog=(Gkc+Kkc*Mkc/Lkc)/math.max(1,Ekc),lane=zkc.Name})
end
Gkc=Gkc+Kkc
end
if Bkc[#Bkc]then
table.insert(bb.samples,{pos=Bkc[#Bkc],prog=1,lane=zkc.Name})
end
end
end
pcall(bb.readHidden,ykc)
bb.laneCut,bb.laneWant,bb.laneFirst=nil,nil,nil
local Okc=tonumber(bb.ld and bb.ld._portal_lanes)
local Pkc=gb.laneList(bb.samples)
if Okc and Okc>=1 and Pkc and#Pkc>Okc then
bb.laneWant=Okc
end
bb.laneTotal=Pkc and#Pkc or 1
bb.countLanes()
end
function bb.readHidden(Qkc)
local Rkc=N.PATH and N.PATH.HIDDEN_MOCK_LANES
if type(Rkc)~=vee[1967]or not next(Rkc)or not(bb.ld and bb.ld.map)or not bb.samples[1]then
return
end
local Skc
for Tkc,Ukc in pairs(Qkc)do
if Rkc[Tkc.Name]and type(Ukc.points)==vee[1967]and#Ukc.points>=2 then
local Vkc={}
for Wkc,Xkc in ipairs(Ukc.points)do
Vkc[Wkc]=U.flat(Xkc.part.Position)
end
local Ykc={}
for Zkc,_kc in ipairs(bb.samples)do
local alc=tostring(_kc.lane)
Ykc[alc]=Ykc[alc]or{}
table.insert(Ykc[alc],_kc)
end
local blc,clc
for dlc,elc in pairs(Ykc)do
local flc=0
for glc=1,#Vkc,math.max(1,math.floor(#Vkc/20))do
local hlc=math.huge
for ilc,jlc in ipairs(elc)do
local klc=(U.flat(jlc.pos)-Vkc[glc]).Magnitude
if klc<hlc then
hlc=klc
end
end
flc=flc+hlc
end
if not clc or flc<clc then
blc,clc=dlc,flc
end
end
local llc,mlc,nlc,olc,plc,qlc={},nil,nil,nil,0,0
for rlc,slc in ipairs(Vkc)do
local tlc,ulc=nil,math.huge
for vlc,wlc in ipairs(Ykc[blc])do
local xlc=(U.flat(wlc.pos)-slc).Magnitude
if xlc<ulc then
ulc,tlc=xlc,wlc.prog
end
end
qlc=math.max(qlc,ulc)
if nlc then
local ylc=tlc-nlc
local zlc=(ylc>0.002 and 1)or(ylc< -0.002 and-1)or olc
if olc and zlc and zlc~=olc then
table.insert(llc,math.floor(nlc*1000+0.5)/1000)
end
olc,plc=zlc or olc,plc+math.abs(ylc)
else
mlc=tlc
end
nlc=tlc
if rlc%50==0 then
task.wait()
end
end
if nlc and qlc<=8 then
table.insert(llc,math.floor(nlc*1000+0.5)/1000)
Skc=Skc or{}
Skc[Tkc.Name]={from=math.floor((mlc or 0)*1000+0.5)/1000,len=math.floor(plc*1000+0.5)/1000,turns=llc,road=blc}
end
end
end
if not Skc then
return
end
local Alc=bb.ld.map
P.maps[Alc]=P.maps[Alc]or{}
local Blc=P.maps[Alc].hidden
P.maps[Alc].hidden=Skc
if type(Blc)~=vee[1967]then
for Clc,Dlc in pairs(Skc)do
F.log(1,vee[2627],string.format(vee[3986],Clc,Dlc.len,tostring(Dlc.road),math.floor((#Dlc.turns-1)/2)))
end
F.saveSoon()
end
end
function bb.countLanes()
local Elc,Flc,Glc={},0,0
for Hlc,Ilc in ipairs(bb.samples)do
local Jlc=tostring(Ilc.lane)
if not Elc[Jlc]then
Flc=Flc+1
end
Elc[Jlc]=(Elc[Jlc]or 0)+1
Glc=Glc+1
end
bb.laneCount={n=Flc,by=Elc,avg=Flc>0 and Glc/Flc or 1}
if Flc>=2 then
local Klc,Llc=pcall(gb.laneSep,bb.samples)
local Mlc=P.maps[bb.mapKey()]
if Klc and Llc and type(Mlc)==vee[1967]then
Mlc.sep=Llc
end
end
end
bb.LANE_WAIT=3
function bb.portalLanes()
if not bb.laneWant or bb.laneCut then
return true
end
if bb.planning then
return false
end
local Nlc,Olc={},0
for Plc,Qlc in ipairs(workspace._UNITS:GetChildren())do
local Rlc=Qlc:FindFirstChild(vee[2030])
if Rlc and Rlc:FindFirstChild(vee[3987])and Rlc.player.Value==nil and Rlc:FindFirstChild(vee[3988])and Qlc:FindFirstChild(vee[3186])then
local Slc=tostring(Rlc.lane.Value)
if not Nlc[Slc]then
Nlc[Slc]=true
Olc=Olc+1
end
end
end
if Olc==0 then
if U.now()-(bb.startT or U.now())>45 then
bb.laneWant=nil
F.log(1,vee[2627],vee[3989])
return true
end
return false
end
bb.laneFirst=bb.laneFirst or U.now()
if Olc<bb.laneWant and U.now()-bb.laneFirst<bb.LANE_WAIT then
return false
end
local Tlc,Ulc={},{}
for Vlc,Wlc in ipairs(bb.samples)do
if Nlc[tostring(Wlc.lane)]then
table.insert(Tlc,Wlc)
end
end
if#Tlc==0 then
bb.laneWant=nil
return true
end
for Xlc in pairs(Nlc)do
table.insert(Ulc,Xlc)
end
table.sort(Ulc)
bb.samples,bb.laneCut=Tlc,table.concat(Ulc,vee[2281])
bb.countLanes()
local Ylc,Zlc=pcall(bb.buildCandidates)
if not Ylc then
F.log(1,vee[2353],vee[3990]..tostring(Zlc))
end
F.log(1,vee[2627],string.format(vee[3991],bb.laneWant,bb.laneCut))
if bb.info and O.simSpots and not bb.joinedMid and not bb.random and not bb.infinite and not bb.trialId then
bb.planning=U.now()
task.spawn(function()
local _lc,amc=pcall(bb.planSpots)
bb.planning=nil
