end
end
if O.infiniteStop and not bb.stopping and ab.partyRole()~=vee[3480]and bb.kind~=vee[2421]then
local imc,jmc=pcall(bb.infStop,fmc)
if not imc then
F.log(1,vee[2353],vee[3994]..tostring(jmc))
end
end
local kmc=W.infTier(fmc-1)
