function bb.infStop(omc)
local pmc=0
for qmc,rmc in ipairs(U.list(N.GS.DAILY_INFINITE_REWARDS))do
pmc=math.max(pmc,tonumber(rmc.wave)or 0)
end
if pmc<=0 or omc<=pmc+1 then
return
end
local smc=P.train.on
if bb.trainee and smc and smc.have+(smc.got or 0)+(bb.trainTk or 0)<smc.need then
return
end
if not ab.every(vee[3998],60)then
return
end
local tmc=W.rec(bb.key)
local umc=tonumber(tmc.timed)or 0
local vmc=W.INF_PAY
local wmc
if omc>=(vmc.cap+vmc.less)/vmc.per then
wmc=0
else
local xmc=bb.infWaveAt or{}
local ymc,zmc=xmc[omc],xmc[omc-5]
if ymc and zmc and ymc>zmc then
wmc=vmc.per*5/((ymc-zmc)/60)
end
if not wmc then
wmc=(umc>0 and(tmc.sec or 0)>0)and math.max(0.5,(tmc.gems or 0)/(tmc.sec/60))or 2.5
end
end
local Amc=pcall(W.pick)
local Bmc
for Cmc,Dmc in ipairs(Amc and W.lastScored or{})do
if Dmc.kind~=vee[1986]and(not Bmc or(Dmc.score or 0)>(Bmc.score or 0))then
Bmc=Dmc
end
end
if not Bmc or(Bmc.score or 0)<=wmc then
return
end
bb.stopping=true
F.log(1,vee[2627],string.format(vee[3999],omc,wmc,Bmc.score,Bmc.label))
bb.sellAll()
end
function bb.trainLeave(Emc)
local Fmc=P.train.on
if not(bb.infinite and bb.trainee and Fmc)then
return
end
bb.trainCount()
local Gmc=Fmc.have+(Fmc.got or 0)+(bb.trainTk or 0)
if Gmc<Fmc.need then
return
end
local Hmc,Imc,Jmc=pcall(W.infDaily,N.prof(),bb.ld.id,(W.infReach(bb.key)))
if Hmc and(Imc or 0)>0 and Jmc>0 and Emc<=Jmc then
F.status(vee[3150],string.format(vee[4000],V.name(Fmc.id),Fmc.what,Jmc))
return
end
bb.stopping=true
F.log(1,vee[2627],string.format(vee[4001],V.name(Fmc.id),Fmc.what,U.fmt(Gmc),U.fmt(Fmc.need),Emc))
bb.sellAll()
end
