function bb.blockers()
local voc=os.clock()
if bb.blockersAt and voc-bb.blockersAt<0.5 and bb.blockersList then
return bb.blockersList
end
local woc=game:GetService(vee[4020])
local xoc={}
for yoc,zoc in ipairs(bb.mine or{})do
