local Ioc=Foc:FindFirstChild(vee[2030])
local Joc=Ioc and Ioc:FindFirstChild(vee[3987])
local Koc=Ioc and Ioc:FindFirstChild(vee[4005])
Hoc=Joc~=nil and Joc.Value~=nil and not(Koc and Koc.Value)and Ioc:FindFirstChild(vee[2058])~=nil
end
if Hoc then
table.insert(Aoc,{p=U.flat(Goc.Position),r=math.max(Goc.Size.X,Goc.Size.Z)/2})
end
