function bb.valid(Loc,Moc,Noc)
local Ooc=N.PC.raycast(Loc+Vector3 .new(0,40,0),Vector3 .new(0,-120,0))
if not Ooc then
return nil
end
if not N.PC.is_valid_raycast_hit(Ooc.Instance,Moc)then
return nil
end
local Poc=Ooc.Position
if bb.blockedSpot(Poc)then
return nil
end
local Qoc=(tonumber(Moc.override_hitbox_radius)or 1.5)+0.25
bb.probe.Size=Vector3 .new(Qoc*2,2.5,Qoc*2)
bb.probe.CFrame=CFrame.new(Poc+Vector3 .new(0,1.35,0))
if#workspace:GetPartsInPart(bb.probe,bb.overlap)>0 then
return nil
end
local Roc=U.flat(Poc)
for Soc,Toc in ipairs(bb.mine or{})do
local Uoc=Toc:FindFirstChild(vee[4022])
local Voc=Uoc and Uoc.Position or Toc:GetPivot().Position
local Woc=Uoc and math.max(Uoc.Size.X,Uoc.Size.Z)/2 or 1.5
if(Roc-U.flat(Voc)).Magnitude<Qoc+Woc then
return nil
end
end
if not Noc then
for Xoc,Yoc in ipairs(bb.blockers())do
if(Roc-Yoc.p).Magnitude<Qoc+Yoc.r then
return nil
end
end
end
return Poc
end
function bb.buildCandidates()
bb.cands={}
local Zoc={}
for _oc=1,#bb.samples,3 do
local apc=bb.samples[_oc]
local bpc=bb.samples[math.min(#bb.samples,_oc+1)]
local cpc=U.flat(bpc.pos-apc.pos)
if cpc.Magnitude<0.01 then
cpc=Vector3 .new(1,0,0)
end
cpc=cpc.Unit
local dpc=Vector3 .new(-cpc.Z,0,cpc.X)
for epc,fpc in ipairs({3,4.5,6,8,10.5,13.5,17})do
for gpc,hpc in ipairs({1,-1})do
local ipc=apc.pos+dpc*fpc*hpc
local jpc=string.format(vee[4019],math.floor(ipc.X/1.5),math.floor(ipc.Z/1.5))
if not Zoc[jpc]then
Zoc[jpc]=true
table.insert(bb.cands,ipc)
end
end
end
end
end
function bb.coverage(kpc,lpc)
local mpc={}
for npc,opc in ipairs(kpc)do
local ppc=opc._stats
if not V.isFarm(ppc.id.Value)and ppc:FindFirstChild(vee[2219])then
table.insert(mpc,{p=U.flat(opc:GetPivot().Position),r=ppc.range.Value*(V.SUMMONER[ppc.id.Value]and V.SUMMONER[ppc.id.Value].reach or 1),air=bb.canAir(opc)})
end
end
local qpc,rpc=0,0
if#mpc>0 then
for spc,tpc in ipairs(bb.samples)do
if tpc.prog>rpc then
local upc=U.flat(tpc.pos)
for vpc,wpc in ipairs(mpc)do
if(upc-wpc.p).Magnitude<=wpc.r then
if tpc.prog>qpc then
qpc=tpc.prog
end
if wpc.air then
rpc=tpc.prog
break
end
end
end
end
end
end
local xpc,ypc={},bb.laneCount
if ypc and ypc.n>=2 and#mpc>0 then
local zpc={}
for Apc,Bpc in ipairs(bb.samples)do
local Cpc=U.flat(Bpc.pos)
for Dpc,Epc in ipairs(mpc)do
if(Cpc-Epc.p).Magnitude<=Epc.r then
local Fpc=tostring(Bpc.lane)
zpc[Fpc]=(zpc[Fpc]or 0)+1
if Bpc.prog>(xpc[Fpc]or 0)then
xpc[Fpc]=Bpc.prog
end
break
end
end
end
local Gpc,Hpc={},0
for Ipc,Jpc in pairs(ypc.by)do
Gpc[Ipc]=(zpc[Ipc]or 0)/math.max(1,Jpc)
Hpc=math.max(Hpc,Gpc[Ipc])
end
bb.laneW={}
for Kpc,Lpc in pairs(ypc.by)do
bb.laneW[Kpc]=(ypc.avg/math.max(1,Lpc))*(1+1.5*(Hpc>0 and(1-Gpc[Kpc]/Hpc)or 0))
end
bb.laneFrac=Gpc
else
bb.laneW,bb.laneFrac=nil,nil
end
local Mpc,Npc,Opc
if#mpc>0 then
for Ppc,Qpc in ipairs(lpc)do
local Rpc=(bb.laneW and Qpc.lane)and(xpc[tostring(Qpc.lane)]or 0)or qpc
if Qpc.hp>0 and Qpc.prog>Rpc+0.02 and Qpc.prog>(Mpc or 0)then
Mpc,Opc=Qpc.prog,bb.laneW and Qpc.lane or nil
end
if Qpc.hp>0 and Qpc.fly and Qpc.prog>rpc+0.02 then
Npc=true
end
end
end
local Spc= #mpc>0 and(bb.pressure or 0)>=qpc-0.08
return{covEnd=qpc,airEnd=rpc,leak=Mpc,leakLane=Opc,covL=xpc,airLeak=Npc,push=Spc,units= #mpc}
end
function bb.needLastLine(Tpc)
