V._airFrom={}
function V.airFrom(gqc)
local hqc=V._airFrom[gqc]
if hqc~=nil then
return hqc or nil
end
local iqc=N.Units[gqc]
if iqc and(iqc.hill_unit or iqc.hybrid_placement or V.SUMMONER[gqc])then
V._airFrom[gqc]=0
