end
local jqc=V.rows(gqc)
if not(jqc and jqc.max)then
return bb.cardAir(gqc)and 0 or nil
end
local kqc=false
for lqc=0,jqc.max do
local mqc=jqc[lqc]and jqc[lqc].atk
if mqc and N.Attacks[mqc]and N.Attacks[mqc].targets_flying then
kqc=lqc
break
end
end
if kqc==false and bb.cardAir(gqc)then
kqc=0
end
V._airFrom[gqc]=kqc
return kqc or nil
end
function bb.cardAir(nqc)
