local vqc,wqc=pcall(bb.liveDps,tqc,uqc)
wqc=vqc and wqc or 0
qqc=qqc+wqc
if bb.canAir(tqc)then
rqc=rqc+wqc
end
end
end
return qqc>0 and rqc/qqc or 0
end
