function bb.cover(zrc,Arc,Brc,Crc,Drc)
local Erc=0
local Frc=U.flat(zrc)
local Grc=Brc and P.maps[bb.mapKey()]and P.maps[bb.mapKey()].dens
local Hrc=bb.laneW
for Irc,Jrc in ipairs(Drc and bb.samples or bb.hurtSamples())do
if(U.flat(Jrc.pos)-Frc).Magnitude<=Arc then
local Krc=1
if Grc then
Krc=0.15+0.85*(tonumber(Grc[math.min(gb.BINS,math.floor(Jrc.prog*gb.BINS)+1)])or 0)
end
if Hrc then
Krc=Krc*(Hrc[tostring(Jrc.lane)]or 1)
end
if Crc then
if Crc.leak and Jrc.prog>=Crc.leak-0.01 and(not Crc.leakLane or tostring(Jrc.lane)==Crc.leakLane)then
Krc=Krc+3
elseif Crc.push and Jrc.prog>Crc.covEnd then
Krc=Krc+0.6
end
end
Erc=Erc+Krc
end
end
return Erc
end
