xIc,yIc=math.min(xIc,JIc.prog),math.max(yIc,JIc.prog)
end
end
end
end
end
if yIc<=xIc then
xIc,yIc=0.75,0.98
end
local KIc=(vIc or zIc)+1
local LIc=({xIc,yIc,(xIc+yIc)/2,xIc-(yIc-xIc)/2})[KIc]
