local hMc=0
for iMc,jMc in ipairs(xLc)do
local kMc=(U.flat(jMc.pos)-U.flat(WLc)).Magnitude
if kMc<=EKc then
hMc=hMc+jMc.dps*(1.1-0.1*kMc/math.max(1,EKc))
end
end
XLc=hMc/yLc*100+bb.cover(WLc,EKc,true)*0.05
else
local lMc=bb.cover(WLc,EKc,true,sKc)
if FKc then
lMc=bb.cover(WLc,FKc)+lMc*0.25
end
XLc=lMc+(TLc and 0 or(1-bb.progressAt(WLc))*0.5)
local mMc=0
for nMc,oMc in ipairs(wLc)do
local pMc=oMc.b.types[vLc]
if pMc and(U.flat(oMc.pos)-U.flat(WLc)).Magnitude<=oMc.range then
mMc=math.max(mMc,math.min(pMc,mMc+pMc*oMc.b.uptime))
end
end
XLc=XLc*(1+mMc)
end
if DLc and(U.flat(DLc)-U.flat(WLc)).Magnitude<=ELc then
XLc=XLc+1e6
end
if FLc and(U.flat(FLc)-U.flat(WLc)).Magnitude<=GLc then
XLc=XLc+1e6
end
if HLc then
table.insert(HLc,{p=WLc,sc=XLc})
end
if not QLc or XLc>QLc then
PLc,QLc,RLc=WLc,XLc,bb.cover(WLc,EKc)
end
end
end
if GKc and#xLc>0 and PLc then
local qMc=false
for rMc,sMc in ipairs(xLc)do
if(U.flat(sMc.pos)-U.flat(PLc)).Magnitude<=EKc then
qMc=true
break
end
end
if not qMc then
return nil,0
end
end
if HLc and#HLc>0 then
table.sort(HLc,function(tMc,uMc)
return tMc.sc>uMc.sc
end)
for vMc=1,math.min(15,#HLc)do
local wMc,xMc=HLc[vMc].p,0
for yMc=0,7 do
local zMc=yMc*math.pi/4
if bb.valid(wMc+Vector3 .new(math.cos(zMc),0,math.sin(zMc))*5,rKc)then
xMc=xMc+1
end
if xMc>=2 then
break
end
end
if xMc>=2 then
return wMc,bb.cover(wMc,EKc)
end
end
end
return PLc,RLc or 0
end
function bb.lookAt(AMc)
local BMc,CMc=math.huge,nil
