local FMc=(U.flat(EMc.pos)-U.flat(AMc)).Magnitude
if FMc<BMc then
BMc,CMc=FMc,EMc.pos
end
end
local GMc=CMc and U.flat(CMc-AMc)or Vector3 .new(0,0,-1)
return GMc.Magnitude>0.01 and GMc.Unit or Vector3 .new(0,0,-1)
end
