function bb.buffGain(CRc)
local DRc=V.allyBuff(CRc.id)
if not DRc then
return 0
end
local ERc=bb.buffShort(DRc)
local FRc=P.stack[DRc.attack]
local GRc=FRc and FRc.stacks and(FRc.cap or 1)or nil
local HRc,IRc=pcall(V.range,CRc.u,0)
IRc=(HRc and tonumber(IRc)or 15)*((bb.info and tonumber(bb.info.rangeScale))or 1)
local JRc=GRc and O.community and tonumber(DRc.time)and tonumber(DRc.cd)
local function KRc(LRc,MRc)
local NRc=math.floor(LRc*DRc.time/math.max(1,DRc.cd)+0.001)
return math.min(GRc,(1+MRc)^NRc-1)
end
local ORc=0
for PRc,QRc in ipairs(ERc)do
local RRc=0
for SRc,TRc in ipairs(ERc)do
if(TRc.pos-QRc.pos).Magnitude<=IRc then
local URc=DRc.types[TRc.base]
local VRc=URc*DRc.uptime
if JRc then
local WRc,XRc=KRc(TRc.n,URc),TRc.n+1
while XRc<TRc.n+6 and KRc(XRc,URc)<=WRc+0.001 do
XRc=XRc+1
end
VRc=math.max(0,(KRc(XRc,URc)-WRc)/(XRc-TRc.n))
elseif GRc then
VRc=math.max(0,math.min(GRc,(TRc.n+1)*URc*DRc.uptime)-math.min(GRc,TRc.n*URc*DRc.uptime))
end
RRc=RRc+TRc.dps*VRc
end
end
ORc=math.max(ORc,RRc)
end
return ORc*(JRc and 1 or 0.7)
end
