function db.settingsOf()
local bod,cod={},0
for dod,eod in pairs(N.DEFAULTS)do
local fod=O[dod]
local god=type(fod)
local hod=god==vee[1969]or god==vee[1968]or(god==vee[875]and#fod<=24 and not fod:find(vee[4716])and not tostring(dod):lower():find(vee[4717]))
if fod~=eod and hod and not db.SETTINGS_SKIP[dod]and not tostring(dod):find(vee[4718])and not tostring(dod):find(vee[4719])then
bod[dod]=god==vee[1968]and math.floor(fod*100+0.5)/100 or fod
cod=cod+1
end
end
return cod>0 and bod or nil
end
function db.searchOf(iod)
local jod=P.simTeam[iod]
if type(jod)~=vee[1967]or type(jod.ids)~=vee[1967]or os.time()-(tonumber(jod.at)or 0)>7200 then
return nil
end
local kod={}
for lod,nod in ipairs(bb.team or{})do
kod[nod.id]=true
end
local ood= #jod.ids>0
for pod,qod in ipairs(jod.ids)do
if not kod[qod]then
ood=false
end
end
return{ids=jod.ids,won=jod.won and true or false,wave=jod.wave,cur=jod.cur,better=jod.better and true or nil,played=ood,ago=os.time()-(tonumber(jod.at)or 0)}
end
