table.insert(tqd,vqd)
end
end
pqd.waves=tqd
qqd=U.json(pqd)
if#qqd<=3900 then
return qqd
end
end
for wqd,xqd in ipairs(pqd.placed or{})do
xqd.why=nil
end
qqd=U.json(pqd)
if#qqd<=3900 then
return qqd
end
if pqd.mapData then
pqd.mapData.dens=nil
end
qqd=U.json(pqd)
if#qqd<=3900 then
return qqd
end
pqd.placed,pqd.plan=nil,nil
qqd=U.json(pqd)
if#qqd<=3900 then
return qqd
end
pqd.settings=nil
