local wPd,xPd,yPd,zPd={},nil,1,#uPd
while yPd<=zPd do
local APd=uPd:find(vee[5246],yPd)
if not APd then
break
end
local BPd
if APd==1 or not uPd:sub(APd-1,APd-1):match(vee[5242])then
for CPd,DPd in ipairs(vPd[uPd:sub(APd,APd+1)]or{})do
if uPd:sub(APd,APd+ #DPd-1)==DPd and not uPd:sub(APd+ #DPd,APd+ #DPd):match(vee[5242])then
BPd=DPd
break
end
end
end
if BPd then
table.insert(wPd,uPd:sub(yPd,APd-1))
table.insert(wPd,vee[2399])
xPd=xPd or{}
table.insert(xPd,BPd)
yPd=APd+ #BPd
else
table.insert(wPd,uPd:sub(yPd,APd))
yPd=APd+1
end
end
table.insert(wPd,uPd:sub(yPd))
return table.concat(wPd),xPd
end
function nb.L.fill(EPd,FPd,GPd)
local HPd,IPd=0,0
EPd=EPd:gsub(vee[5247],function(JPd)
if JPd~=vee[889]then
return FPd[tonumber(JPd)]or vee[889]
end
HPd=HPd+1
return FPd[HPd]or vee[889]
end)
if GPd then
EPd=EPd:gsub(vee[5248],function(KPd)
if KPd~=vee[889]then
return GPd[tonumber(KPd)]or vee[889]
end
IPd=IPd+1
return GPd[IPd]or vee[889]
end)
end
return EPd
end
function nb.L.piece(LPd)
local MPd=nb.L
local NPd=MPd.dict
local OPd,PPd,QPd=MPd.core(LPd)
if PPd==vee[889]then
return nil
end
local RPd=NPd[PPd]or MPd.low[PPd:lower()]
if not RPd and PPd:find(vee[872])then
local SPd,TPd=MPd.key(PPd)
local UPd=NPd[SPd]or MPd.low[SPd:lower()]
if UPd then
RPd=MPd.fill(UPd,TPd)
end
end
if not RPd then
local VPd,WPd=MPd.slot(PPd)
if WPd then
local XPd,YPd=MPd.key(VPd)
local ZPd=NPd[XPd]or MPd.low[XPd:lower()]
if ZPd then
RPd=MPd.fill(ZPd,YPd,WPd)
end
end
end
return RPd and(OPd..RPd..QPd)or nil
end
function nb.L.colon(_Pd)
